import{_ as a,o as t,c as s,a5 as o}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"永続化と確実な復旧","description":"","frontmatter":{"title":"永続化と確実な復旧","docId":"developer.storage","translationKey":"developer.storage","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"7ec9d94e484af17e8e82aaaa2122cc47ecd206cf9306047795d6aaa72eea2edb","translationRevision":"4b0d4e93e515898bc2dd78d1783299890afd6aebe472be9c8734a2fbcb5ef56d","order":60},"headers":[],"relativePath":"ja/developer/storage.md","filePath":"ja/developer/storage.md","lastUpdated":1794611623000}'),i={name:"ja/developer/storage.md"};function r(d,e,l,c,n,h){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="persistence-and-durable-recovery" tabindex="-1">永続化と確実な復旧 <a class="header-anchor" href="#persistence-and-durable-recovery" aria-label="Permalink to &quot;永続化と確実な復旧 {#persistence-and-durable-recovery}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>担当サービスを通して永続状態を変え、復旧可能な結果を保ちます。使い捨てプロファイルを使い、DB コピー前にホストを閉じ、バージョン付きリソース編集前に<a href="./control-api.html">制御メタデータ</a> を読みます。<code>TIKTOOLS_HOME</code> がルートを選び、<code>AppPaths</code> がデータと非公開ストアを解決します。</p><h2 id="identify-the-store" tabindex="-1">保存先を特定する <a class="header-anchor" href="#identify-the-store" aria-label="Permalink to &quot;保存先を特定する {#identify-the-store}&quot;">​</a></h2><p><code>crates/tiktools-core/src/paths.rs</code> が <code>data/tiktok-points.db</code>、<code>data/tiktok-automation.db</code>、<code>data/tiktok-analytics.db</code> を定義します。各 SQLite サービスがスキーマを所有します。ポイント・視聴者と自動化定義は別台帳、統計も独立 DB で、古い2 DB 構成図には統計がありません。</p><p>起動時、保存先がない場合だけチェックアウト内の旧 DB を環境のアプリデータへコピーできます。既存の保存先は上書きしません。ネイティブ実行の変更中も JSON 定義を読み取れます。ユーザープロファイルの削除や Vue からのテーブル再書き込みで移行を実装しないでください。</p><h2 id="make-a-recoverable-change" tabindex="-1">復旧可能な変更を行う <a class="header-anchor" href="#make-a-recoverable-change" aria-label="Permalink to &quot;復旧可能な変更を行う {#make-a-recoverable-change}&quot;">​</a></h2><ol><li>サービスのトランザクションとスキーマ・移行テストを探します。</li><li>対応ドメインでは業務変更、リビジョン、必要なジャーナル・outbox 予約を同じトランザクションに保存します。</li><li>削除時のリビジョン墓標を保持します。再利用 ID は削除前の編集リビジョンを受け付けてはいけません。</li><li>既存 outbox からコミット済み無効化情報を公開します。配信再試行で元の処理を繰り返しません。</li><li>中断後は同じ非公開ホームを開き、別変更の前に元のコマンドを解決します。</li></ol><p>起動済みテストホストでの読み取り専用確認例です。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span></code></pre></div><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>対応する永続ワークフロー、ポイント、所有者ジャーナルは再起動後も元の結果を保持します。受領記録は過去のコマンドを表し、現在の状態は別に読みます。Cloud ワークスペースの保存にはオリジン・アカウント分割と世代検査がありますが、ローカル SQLite の権威を置き換えません。外部処理やドメインすべてが同じ復旧範囲を持つわけではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>オフラインバックアップでは SQLite と存在する WAL/SHM をまとめて保管します。UI タイムアウトはロールバックの証拠ではありません。<code>revision_conflict</code> は下書きを保持して新しい読み取りと比較します。外部処理が不確実ならフィードを再実行せず保持した処理記録を調べます。<a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/paths.rs" target="_blank" rel="noreferrer">パスの正本</a> と <a href="./cloud.html">Cloud 復旧</a> で別々の境界を確認します。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>試験・バックアップ前に <code>tiktools api call system.info --json</code> で実パスを確認します。<code>TIKTOOLS_HOME</code> がルートを選び、<code>TIKTOOLS_DATA_DIR</code>、<code>TIKTOOLS_PLUGINS_DIR</code>、<code>TIKTOOLS_PLUGIN_DATA_DIR</code>、<code>TIKTOOLS_PLUGIN_STORE_DIR</code>、<code>TIKTOOLS_LOG_DIR</code>、<code>TIKTOOLS_TEMP_DIR</code> が派生先を個別に上書きします。相対パスは起動ディレクトリ基準です。home の分離だけでは継承変数を無効化できないため先に確認・解除します。</p><p>Analytics は集計データを専用ライターで書きます。現在のキューは 1,024 件、バッチ 128 件、flush 期限 10 秒です。データベースパスから隣接 <code>*.pending.json</code> を作ります。起動時に ID 付きバッチを再適用し、回復ファイルを除いてから <code>ready</code> が新規処理を許可します。読めない・16 MiB 超の回復ファイル、使用不能な DB、回復ファイル削除失敗では受け付けを停止します。DB と回復ファイルを保持し、<code>ready</code>・未処理件数・エラーを確認して修復前に保存します。健全に見せるための削除はしません。ポイントログは別の耐久性契約です。</p><p><code>system.info</code> は実 home/dataDir を返します。他のディレクトリは別端末ではなくホストの実起動環境で解決します。<code>system.health</code> は集計 ready/未処理と LIVE 入口カウンターを提供します。</p>`,18)])])}const u=a(i,[["render",r]]);export{k as __pageData,u as default};
